/** Original Adobe Source Serif 4 variable TTFs, release 4.005R. See licenses/SourceSerif4-OFL.txt. */

/** The same unmodified originals supply browser registration and portable outline shaping. */
export class DesignSourceSerifBytes {
    /** Original roman or italic font bytes; callers retain ownership of the returned buffer. */
    public static read(italic: boolean): Uint8Array<ArrayBuffer> {
        return Uint8Array.from(atob(this.encoded(italic)), (character: string): number =>
            character.charCodeAt(0),
        );
    }

    /** Explicit SVG exports embed only the referenced style, with its original license. */
    public static encoded(italic: boolean): string {
        return italic
            ? ''
            : '';
    }
}
